const chip=(t,id)=>{const x=E.team(t,id);return `<span class="team-chip"><i class="color-dot" style="--color:${safeColor(x?.color)}"></i>${esc(x?.name)}</span>`};
const safeColor=c=>/^#[0-9a-f]{6}$/i.test(c??'')?c:'#315ae8';
function initialData(){return {schema:1,updatedAt:0,revision:0,events:[],activeId:null}}
function load(){for(const key of[KEY,BACKUP])try{const v=JSON.parse(localStorage.getItem(key));if(validData(v))return v}catch{}return initialData()}
function validData(v){return !!v&&v.schema===1&&Array.isArray(v.events)&&v.events.every(e=>typeof e.id==='string'&&typeof e.title==='string'&&Array.isArray(e.tournaments)&&e.tournaments.length>0&&e.tournaments.length<=20&&e.tournaments.every(t=>t&&typeof t.id==='string'&&E.SPORTS[t.config?.sport]&&E.FORMULAS[t.config?.formula]&&Array.isArray(t.teams)&&Array.isArray(t.courts)&&Array.isArray(t.rotations)&&t.rotations.length>0&&t.rotations.every(r=>Array.isArray(r.matches)&&r.matches.every(m=>Array.isArray(m.a)&&Array.isArray(m.b)&&Number.isFinite(m.scoreA)&&Number.isFinite(m.scoreB)))&&t.roundIndex>=0&&t.roundIndex<t.rotations.length))}
let data=load(),view='home',tab='courts',draft=null,rankGeneral=false,rankingPage=0,rankingMode='auto',colorEditing=null,projection=false,archiveQuery='',archivePage=0,archiveFilter='all',deletedEvents=[],zoom=1,installEvent=null,audioContext=null,toastTimer=null,dbPromise=null,storageWarning=false,dragMember=null,dragCourtPlayer=null,courtSelected=null,courtClickAfter=0,lastAudioEnd=0;
function normalizeEvent(e){
 if(e.audio?.version!==2)e.audio={...e.audio,version:2,sound:e.audio?.sound==='custom'?'custom':'voice',enabled:e.audio?.enabled??true,volume:e.audio?.volume??.8,start:true,alert30:false,alert60:false};
 for(const t of e.tournaments){t.config.referees??=false;t.config.scoreMode??='normal';t.config.bonusPoints??=3;const individual=P.individualRoster(t.config);for(const [i,x] of t.teams.entries()){
  x.members??=[];
  if(individual&&/^Équipe \d+$/.test(x.name))x.name=x.name.replace('Équipe',t.config.format==='double'?'Duo':'Joueur');
  if(!individual&&/^Équipe \d+$/.test(x.name)){x.name=C.bibIdentity(i).name;x.color=C.bibIdentity(i).color;x.bibNamed=true}
  if(!individual&&x.playerCount==null&&x.members.length)x.playerCount=x.members.length;
 }P.assignReferees(t)}return e
}
data.events.forEach(normalizeEvent);
function rosterTerm(c,plural=false){if(!P.individualRoster(c))return plural?'équipes':'équipe';return c.formula!=='melee'&&c.formula!=='americano'&&(c.playersPerSide===2||c.format==='double')?plural?'duos':'duo':plural?'joueurs':'joueur'}
const capital=s=>s[0].toUpperCase()+s.slice(1);
function validateNames(){if(!draft.teams.every(x=>x.name.trim()))throw Error('Saisissez les noms.');if(new Set(draft.teams.map(x=>x.name.trim().toLocaleLowerCase('fr-FR'))).size!==draft.teams.length)throw Error('Les noms doivent être différents.')}
function validateTiming(){const c=draftCfg();if(c.endMode!=='time')return;const plan=draftTiming();if(!plan.feasible||plan.setup+plan.rotations*c.duration+plan.transitionTotal>plan.budget)throw Error('La séance dépasse le temps du cours. Choisissez une durée plus courte, réduisez les rotations ou ajoutez des terrains.')}
let nextCache=new Map();
const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('eps-tournois'):null;
const event=()=>data.events.find(e=>e.id===data.activeId);
const tourney=()=>event()?.tournaments.find(t=>t.id===event().selectedId)??event()?.tournaments[0];
const hasTournament=()=>!!tourney();
const canScore=m=>!!m;
function db(){if(!('indexedDB'in globalThis))return Promise.reject(Error('IndexedDB indisponible'));return dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('eps-tournoi-offline',1);r.onupgradeneeded=()=>r.result.createObjectStore('snapshots');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function dbWrite(snapshot){const d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('snapshots','readwrite');tx.objectStore('snapshots').put(snapshot,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function restoreDB(){try{const d=await db(),r=d.transaction('snapshots').objectStore('snapshots').get('current');r.onsuccess=()=>{if(validData(r.result)&&r.result.updatedAt>data.updatedAt){data=r.result;data.events.forEach(normalizeEvent);render();toast('Votre sauvegarde a été retrouvée.')}}}catch{}}
function save(){data.updatedAt=Date.now();data.revision=(data.revision??0)+1;const snapshot=JSON.stringify(data);let ok=false;try{const previous=localStorage.getItem(KEY);if(previous)localStorage.setItem(BACKUP,previous);localStorage.setItem(KEY,snapshot);ok=true}catch{try{localStorage.removeItem(BACKUP);localStorage.setItem(KEY,snapshot);ok=true}catch{}}dbWrite(structuredClone(data)).catch(()=>{if(!ok)toast('Sauvegarde impossible : exportez une copie JSON tout de suite.',true)});if(!ok&&!storageWarning){storageWarning=true;toast('Le stockage rapide est plein. Pensez à exporter une sauvegarde JSON.',true)}channel?.postMessage({type:'snapshot',data});}
function sync(v){if(validData(v)&&v.updatedAt>=data.updatedAt){data=v;data.events.forEach(normalizeEvent);render()}}
channel&&(channel.onmessage=e=>{if(e.data?.type==='snapshot')sync(e.data.data)});addEventListener('storage',e=>{if(e.key===KEY&&e.newValue)try{sync(JSON.parse(e.newValue))}catch{}});
function toast(message,persistent=false){clearTimeout(toastTimer);toastNode.textContent=message;toastNode.classList.add('show');if(!persistent)toastTimer=setTimeout(()=>toastNode.classList.remove('show'),4200)}
function dialog(title,content,footer=''){modal.innerHTML=`<div class="modal-header"><h2>${esc(title)}</h2>${btn(icon('close'),'close','icon-only','aria-label="Fermer"')}</div><div class="modal-content">${content}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal()}
let confirmationResolve=null;
function confirmDialog(message,title='Confirmer',accept='Confirmer'){
 if(confirmationResolve)return Promise.resolve(false);
 return new Promise(resolve=>{confirmationResolve=resolve;confirmation.innerHTML=`<div class="modal-header"><h2 id="confirmation-title">${esc(title)}</h2>${btn(icon('close'),'confirm-cancel','icon-only','aria-label="Annuler"')}</div><p>${esc(message)}</p><div class="modal-footer">${btn('Annuler','confirm-cancel')}${btn(accept,'confirm-accept','primary')}</div>`;try{confirmation.showModal()}catch(error){confirmationResolve=null;resolve(false);toast('Confirmation indisponible : '+error.message,true)}});
}
function settleConfirmation(accepted){const resolve=confirmationResolve;if(!resolve)return;confirmationResolve=null;confirmation.close();resolve(accepted)}
function checkRotation(t,id){if(t!==tourney()||E.current(t).id!==id)throw Error('La rotation a changé. Recommencez depuis les terrains.');}
function reportError(error){const where=view==='wizard'?document.getElementById('wizard-error'):modal.open?document.getElementById('match-error'):null;if(where)where.textContent=error.message;else toast(error.message,true)}
function finishFeedback(t){const pending=E.current(t).matches.filter(m=>m.tieBreak&&!E.done(m));if(pending.length)toast('Égalité : '+pending.length+' '+(pending.length>1?'rencontres nécessitent':'rencontre nécessite')+' un point décisif pour désigner le vainqueur.');else if(E.current(t).matches.every(E.done)){sound('end');toast('Matchs terminés. Vous pouvez passer à la rotation suivante.')}else sound('match-end')}
function footer(){return `<footer class="footer"><span>Créé par L. RIGAUX</span><span>${data.updatedAt?'Sauvegardé · '+new Date(data.updatedAt).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}):'Vos tournois restent sur cet appareil'}</span></footer>`}
function brand(){return btn('<span class="brand-mark"><img src="./icon.svg?v=220" alt=""></span><span class="brand-copy"><span class="brand-word">TOURNOI <em>EPS</em></span><span class="brand-credit">Créé par L. RIGAUX</span></span>','home','brand','aria-label="Accueil"')}

function topbar(){return `<header class="topbar">${brand()}<div class="top-actions">${view==='tournament'?`${btn(icon('fullscreen'),'fullscreen','icon-only','aria-label="Plein écran"')}<details class="tournament-menu"><summary>${icon('settings')} Menu</summary><nav class="menu-popover" aria-label="Outils du tournoi">${btn(icon('clock')+' Rencontres et rotations','rotations','')}${P.isIndividual(tourney()?.config.sport)?btn(icon('person')+' Répartir les joueurs','court-players',''):btn(icon(P.individualRoster(tourney().config)?'person':'jersey')+(P.individualRoster(tourney().config)?' Joueurs et couleurs':' Noms, chasubles et logos'),'teams','')}${btn(icon('download')+' Exporter / sauvegarder','exports','')}${btn(icon('settings')+' Réglages','settings','')}${btn(icon('copy')+' Nouvelle séance','session-options','')}${btn(icon('volume')+' Tester les annonces','test-sound','')}</nav></details>`:view==='home'?btn(icon('upload')+' Mes sauvegardes','restore','small'):''}</div></header>`}
function home(){return `${topbar()}<section class="activity-home"><div class="home-heading"><div><span class="eyebrow">EPS · COLLÈGE & LYCÉE</span><h1>Choisir l’activité<span>.</span></h1></div><div class="home-intro"><span class="competition-badge">${icon('trophy')} TOURNOI EPS</span><div class="home-route" aria-label="Préparation de la séance"><span><b>01</b> Activité</span><i>→</i><span><b>02</b> Organisation</span><i>→</i><span><b>03</b> Rencontres</span></div></div></div>${activityCards()}<section class="saved-events ${data.events.length?'has-saved':'empty'}"><div class="flex between"><h2>Mes tournois <span class="saved-count">${data.events.length}</span></h2>${btn(icon('search')+' Rechercher / tous les tournois','archive','small')}${installEvent?btn('Installer','install','small'):''}</div>${deletedEvents.length?`<aside class="undo-bar" role="status"><span>« ${esc(deletedEvents.at(-1).event.title)} » supprimé</span>${btn(icon('undo')+' Annuler','undo-delete','small')}</aside>`:''}<div class="saved-list">${data.events.length?data.events.slice().reverse().slice(0,3).map(e=>{const t=e.tournaments[0];return `<article class="saved-entry">${btn(`<span class="saved-icon">${icon(E.SPORTS[t.config.sport].icon)}</span><span><strong>${esc(e.title)}</strong><small>${esc(t.config.multisport?'Multisport':E.SPORTS[t.config.sport].name)} · ${t.courts.length} ${t.config.sport==='table'?'tables':'terrains'} · ${e.tournaments.every(t=>t.completed)?'Terminé':'En cours'}</small></span>`,'open-event','saved-event',`data-id="${e.id}"`)}${e.tournaments.every(t=>t.completed)?btn(icon('copy'),'session-options','icon-only',`data-id="${e.id}" aria-label="Recommencer ou réutiliser ${esc(e.title)}"`):''}${btn(icon('trash'),'delete-saved','delete-saved icon-only',`data-id="${e.id}" aria-label="Supprimer ${esc(e.title)}" title="Supprimer ce tournoi"`)}</article>`}).join(''):'<p class="muted">Vos tournois enregistrés apparaîtront ici.</p>'}</div></section></section>${footer()}`}
function makeDraftTeams(n,c){return E.makeTeams(n).map((x,i)=>P.individualRoster(c)?{...x,name:capital(rosterTerm(c))+' '+(i+1),homeCourt:Math.floor(i/2)%c.courtCount+1}:{...x,...C.bibIdentity(i),bibNamed:true,playerCount:null})}
function newDraft(s='basket'){const c=defaults(s);draft={step:1,title:'Tournoi '+E.SPORTS[s].name,selected:[s],multi:false,editingSport:s,configs:{[s]:c},count:6,teams:makeDraftTeams(6,c),studentCount:28,mode:null,proposal:null,participants:[],assignment:'balanced',teamPage:0,formulaPage:0,timingPage:0,poolPage:0};view='wizard';render()}
function defaults(s){const individual=P.isIndividual(s);return {sport:s,format:individual?'single':'custom',playersPerSide:individual?1:s==='volley'?3:4,courtCount:3,formula:'rr',endMode:'time',duration:300,target:s==='football'||s==='futsal'||s==='rugby'?3:s==='handball'?5:s==='volley'?15:11,sync:'common',stopPolicy:'individual',tie:'draw',overtime:60,breakSeconds:45,poolCount:2,qualifiers:2,roundCount:5,availableMinutes:90,setupMinutes:10,badmintonCourt:'full',referees:false,winPoints:3,drawPoints:1,lossPoints:0,scoreMode:'normal',bonusPoints:3,customText:''}}
function draftCfg(){return draft.configs[draft.editingSport]}
function clearOpening(){if(draft){delete draftCfg().openingPairs;draftCfg().chooseOpening=false;}}
function resizeTeams(n){clearOpening();n=P.integer(n,2,64);draft.count=n;const additions=makeDraftTeams(n,draftCfg());draft.teams=Array.from({length:n},(_,i)=>draft.teams[i]??additions[i]);}
function assignDraft(){
 clearOpening();const c=draftCfg();if(!draft.participants.length)return;R.validateCourts(draft.participants,c.courtCount);
 let teams;
 if(draft.assignment==='existing'&&draft.participants.some(p=>p.team)){
  const names=[...new Set(draft.participants.map(p=>p.team).filter(Boolean))];teams=names.map((name,i)=>({id:E.uid(),name,color:draft.participants.find(p=>p.team===name&&p.color)?.color??E.COLORS[i%E.COLORS.length],members:draft.participants.filter(p=>p.team===name),level:0,active:true}));draft.participants.filter(p=>!p.team).forEach((p,i)=>teams[i%teams.length].members.push(p));
 }else if(P.individualRoster(c)&&draft.participants.some(p=>!p.placeholder))teams=R.importedTeams(draft.participants,c.formula==='melee'?1:c.playersPerSide);
 else{teams=E.balancedTeams(draft.participants,draft.count,draft.assignment);teams.forEach((x,i)=>x.name=capital(rosterTerm(c))+' '+(i+1))}
 if(teams.length<2||teams.length>64)throw Error('Inscrivez entre 2 et 64 joueurs ou duos.');
 const old=draft.teams;teams.forEach((x,i)=>{const prev=old[i];if(prev){x.color=prev.color;x.logo=prev.logo;if(prev.nameEdited){x.name=prev.name;x.nameEdited=true}}});R.defaultCourts(teams,c.courtCount);
 draft.teams=teams;draft.count=teams.length;draft.teamPage=0;syncMeleeRounds();
}

function field(label,name,value,type='number',extra=''){return `<label class="field"><span>${label}</span><input type="${type}" data-field="${name}" value="${esc(value)}" ${extra}></label>`}
